You must support: push new records, remove by index (compacting the array), and stable external identifiers that clients may cache as pointers to `Record` elements. Records will be reallocated as the array grows via `realloc`.

You need an in-memory serialization of a struct with padding so it can be sent over a socket as a compact byte sequence. The struct:

```c
#include <stdint.h>
#include <stddef.h>

typedef enum { T_INT=1, T_STR=2 } Type;

typedef struct {
    Type   type;    // enum
    uint32_t id;    // host-endian
    char  *name;    // owned pointer, not transferable as-is
} Msg;
```
A teammate proposes to send `sizeof(Msg)` bytes by `memcpy`-ing the struct into a buffer. Another proposes to send only the needed fields into a packed buffer and reconstruct on the other side, allocating for `name` as needed. You cannot change the `Msg` definition.

scenario_questions.expected_answer:
Sending `sizeof(Msg)` is incorrect: it includes padding bytes with unspecified content and the `name` pointer, which is meaningless in another address space. Correct approach is to define a packed, explicit layout that contains only transferable data and reconstruct `Msg` with dynamic allocation for `name`.

Example encode (host-endian kept for brevity; in production, define byte order):

```c
// layout: [1 byte type][4 bytes id][4 bytes name_len][name bytes (no NUL)]
size_t msg_size(const Msg *m) { return 1 + 4 + 4 + (m->name ? (uint32_t)strlen(m->name) : 0); }

int msg_encode(uint8_t *out, size_t out_cap, const Msg *m) {
    uint32_t name_len = m->name ? (uint32_t)strlen(m->name) : 0;
    size_t need = 1 + 4 + 4 + name_len;
    if (out_cap < need) return -1;
    size_t o = 0;
    out[o++] = (uint8_t)m->type;
    memcpy(out + o, &m->id, 4); o += 4;
    memcpy(out + o, &name_len, 4); o += 4;
    if (name_len) { memcpy(out + o, m->name, name_len); o += name_len; }
    return (int)o;
}

int msg_decode(Msg *m, const uint8_t *in, size_t in_len) {
    if (in_len < 1 + 4 + 4) return -1;
    size_t o = 0;
    m->type = (Type)in[o++];
    memcpy(&m->id, in + o, 4); o += 4;
    uint32_t name_len = 0; memcpy(&name_len, in + o, 4); o += 4;
    if (in_len - o < name_len) return -1;
    m->name = NULL;
    if (name_len) {
        m->name = malloc((size_t)name_len + 1);
        if (!m->name) return -1;
        memcpy(m->name, in + o, name_len);
        m->name[name_len] = '\0';
        o += name_len;
    }
    return (int)o;
}
```
This avoids padding, does not transmit meaningless pointers, and uses dynamic memory only to rebuild `name` on the receiver.

